WITH p AS (SELECT %s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_carton,a.id_carton_new,a.date0,a.time0,count(*) OVER() total FROM public.intem_carton_log a CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.unrestricted OR EXISTS(SELECT 1 FROM public.mes_oi_dong_thung t JOIN public.phlsx l ON l.so_ct=t.production_order WHERE (t.serial_tem_thung=a.id_carton OR t.serial_tem_thung=a.id_carton_new) AND l.ma_dvcs=ANY(string_to_array(s.bs,',')))) ORDER BY a.date0 DESC,a.time0 DESC LIMIT(SELECT lim FROM p);
